head.script:
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name ins_search
 * @description 채권 마스터  목록 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search = async function() {
    /**
     * SrM-000243255
     */
    if (!await scwin.checkSearchCondition()) {
        return false;
    }

    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_SISUDATE, edt_EISUDATE) === false) {
        return false;
    }

    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_SDATE, edt_EDATE) === false) {
        return false;
    }
    ckb_BND_ISU_METHD_CD1.setValue("N");
    ckb_BND_ISU_METHD_CD2.setValue("N");
    ckb_BND_ISU_METHD_CD3.setValue("N");
    dts_detail.removeAll();
    dts_callList.removeAll();
    dts_putList.removeAll();
    dts_CreditValuList.removeAll();
    dts_AsstList.removeAll();
    dts_BND_PAY_INT.removeAll();

    // 조회버튼 비활성.
    fn_SetDisableSelectBtn(btn_search, true);
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name checkSearchCondition
 * @description SrM-000243255  조회조건을 체크 (표준코드, 한글종목명, 발행기관코드에 값이 입력 안되었을 경우 / 날짜 조건은 필수로 입력되도록.. 날짜 입력가능 범위는 5년..)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkSearchCondition = async function() {
    const sStdCd = txb_pSTD_CD.getValue();
    const sIsuKorNm = txb_pISU_KOR_NM.getValue();
    const sIsurCd = txb_pISUR_CD.getValue();
    const sIsuDateFrom = edt_SISUDATE.getValue(); // 발행일(from)
    const sIsuDateTo = edt_EISUDATE.getValue(); // 발행일(to)
    const sSDateFrom = edt_SDATE.getValue(); // 코드부여일(from)
    const sSDateTo = edt_EDATE.getValue(); // 코드부여일(to)

    if (sStdCd === "" && sIsuKorNm === "" && sIsurCd === "") {
        if (sIsuDateFrom === "" && sIsuDateTo === "" && sSDateFrom === "" && sSDateTo === "") {
            const msg = "조회조건을 최소 1개 이상 입력하세요.\n\n" + "[표준코드, 한글종목명, 발행기관명(코드)] 중 1개 이상의 조건을 입력하거나, \n" + "[발행일 또는 코드부여일]의 검색기간을 5년 이내로 입력하세요.";
            await $c.win.alert(msg);
            return false;
        }

        // 발행일 체크
        if (sIsuDateFrom !== "" && sIsuDateTo !== "") {
            if (Number($c.ut.cGetPlusYear(sIsuDateFrom, 5)) < Number(sIsuDateTo)) {
                await $c.win.alert("발행일의 검색기간은 5년 이내로 입력하세요.");
                edt_SISUDATE.focus();
                return false;
            }
        } else if (sIsuDateFrom !== "" || sIsuDateTo !== "") {
            await $c.win.alert("발행일의 검색기간은 5년 이내로 입력하세요.");
            if (sIsuDateFrom === "") {
                edt_SISUDATE.focus();
            } else {
                edt_EISUDATE.focus();
            }
            return false;
        }

        // 코드부여일 체크
        if (sSDateFrom !== "" && sSDateTo !== "") {
            if (Number($c.ut.cGetPlusYear(sSDateFrom, 5)) < Number(sSDateTo)) {
                await $c.win.alert("코드부여일의 검색기간은 5년 이내로 입력하세요.");
                edt_SDATE.focus();
                return false;
            }
        } else if (sSDateFrom !== "" || sSDateTo !== "") {
            await $c.win.alert("코드부여일의 검색기간은 5년 이내로 입력하세요.");
            if (sSDateFrom === "") {
                edt_SDATE.focus();
            } else {
                edt_EDATE.focus();
            }
            return false;
        }
    }
    return true;
};

/**
