        ref : "",
        target : "dts_CreditValuList=body.content",
        isProcessMsg : false
    };

    const sbmRtn4 = await $c.sbm.executeDynamic(sbmOptions4);
    // TODO Stage2: sbmRtn4 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 채권 보유기관 마스터
    const sbmOptions5 = {
        id : "sbm_dts_AsstList",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_AsstList=body.content",
        isProcessMsg : false
    };

    const sbmRtn5 = await $c.sbm.executeDynamic(sbmOptions5);
    // TODO Stage2: sbmRtn5 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 채권지급이자 마스터
    const sbmOptions6 = {
        id : "sbm_dts_BND_PAY_INT",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_BND_PAY_INT=body.content",
        isProcessMsg : false
    };

    const sbmRtn6 = await $c.sbm.executeDynamic(sbmOptions6);
    // TODO Stage2: sbmRtn6 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name changeCfi
 * @description cfi 변경 설정
 * @returns {void}
 * @hidden N
 */
scwin.changeCfi = function() {
    // Cfi의 콤보 박스를 변경할 경우....
    let cfi = "";
    cfi = "D";
    if (cmb_cb_p_group.getValue() === "") {
        cfi += "_";
    } else {
        cfi += cmb_cb_p_group.getValue();
    }
    if (cmb_cb_p_attr_1.getValue() === "") {
        cfi += "_";
    } else {
        cfi += cmb_cb_p_attr_1.getValue();
    }
    if (cmb_cb_p_attr_2.getValue() === "") {
        cfi += "_";
    } else {
        cfi += cmb_cb_p_attr_2.getValue();
    }
    if (cmb_cb_p_attr_3.getValue() === "") {
        cfi += "_";
    } else {
        cfi += cmb_cb_p_attr_3.getValue();
    }
    if (cmb_cb_p_attr_4.getValue() === "") {
        cfi += "_";
    } else {
        cfi += cmb_cb_p_attr_4.getValue();
    }
    txb_CFI_CD.setValue(cfi); // cfi 설정
    dts_detail.setCellData(dts_detail.getRowPosition(), "CFI_CD", cfi); // cfi 설정

};

/**
 * @method
 * @name setChange
 * @description 상세 조회시 CFI 상세 설정
 * @param {String} str_cfi str_cfi
 * @returns {void}
 * @hidden N
 */
scwin.setChange = function(str_cfi) {
    if (str_cfi === "") return;
    cmb_cb_p_group.setValue(str_cfi.substring(1, 2));
    cmb_cb_p_attr_1.setValue(str_cfi.substring(2, 3));
    cmb_cb_p_attr_2.setValue(str_cfi.substring(3, 4));
    cmb_cb_p_attr_3.setValue(str_cfi.substring(4, 5));
    cmb_cb_p_attr_4.setValue(str_cfi.substring(5, 6));
};

/**
 * @method
 * @name cOUPNRTDECSNBASINTCDChage
 * @description 이자율결정기준금리 에 따른 기타기준금리 정의
 * @returns {void}
 * @hidden N
 */
scwin.cOUPNRTDECSNBASINTCDChage = function() {
    if (cmb_COUPN_RT_DECSN_BAS_INT_CD.getValue() === "90") {
        txb_INT_RT_DECSN_MISC_BAS_INT_NM.setDisabled(false);
        txb_INT_RT_DECSN_MISC_BAS_INT_NM.ReadOnlyBackColor = 'white';
    } else {
        txb_INT_RT_DECSN_MISC_BAS_INT_NM.setDisabled(true);
        txb_INT_RT_DECSN_MISC_BAS_INT_NM.ReadOnlyBackColor = '#b9d4f7';
        txb_INT_RT_DECSN_MISC_BAS_INT_NM.setValue("");
    }
};

/**
 * @method
 * @name setBndView
 * @description 채권 상세화면을 정의한다.
 * @param {*} SIMSA_YN SIMSA_YN
 * @param {String} LIST_STAT_CD LIST_STAT_CD
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setBndView = async function(SIMSA_YN, LIST_STAT_CD) {
    if (LIST_STAT_CD === "N" && SIMSA_YN === "Y") {
        await $c.win.alert(" 해당종목은 신규상장심사종목입니다. \n" + " 수정후에는 반드시 채권심사종목정보도 수정이 되도록 채권상장팀에 통보를 하셔야 됩니다.");
    } else if (LIST_STAT_CD === "Y") {
        // alert(" 상장채권은 수정할 수 없습니다 \n" + " 채권상장팀과 협의하시기 바랍니다");
        btn_modify.setDisabled(true);
        btn_modify.setBackgroundImage("../img/ins/btn_modify_d.gif");
        btn_delete.setDisabled(true);
        btn_delete.setBackgroundImage("../img/ins/btn_delete_d.gif");

        // alert 삭제 및 비밀번호 초기화도 제어 추가 20140116
        btn_clearPwd.setDisabled(true);
        btn_clearPwd.setBackgroundImage("../img/ins/btn_clearPwd_d.gif");
    } else {
        btn_modify.setDisabled(false);
        btn_modify.setBackgroundImage("../img/ins/btn_modify.gif");
        btn_delete.setDisabled(false);
        btn_delete.setBackgroundImage("../img/ins/btn_delete.gif");
        btn_clearPwd.setDisabled(false);
        btn_clearPwd.setBackgroundImage("../img/ins/btn_clearPwd.gif");
    }
};

/**
 * @method
 * @name formCheck
 * @description 폼을 체크한다.
 * @param {*} Typ Typ
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.formCheck = async function(Typ) {
    // textarea 개행문자제거
    txa_NUSUAL_ISU_COND_CONTN.text = txa_NUSUAL_ISU_COND_CONTN.text.replace(/[\r|\n]/g, "");
    txa_MEMO_CONTN.text = txa_MEMO_CONTN.text.replace(/[\r|\n]/g, "");
