        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행기관코드"));
        txb_ISUR_CD.focus();
        return false;
    }
    if (txb_ISU_NM.getValue() === "" || txb_ISU_NM.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글기준명"));
        txb_ISU_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ABBRV, 60, "한글기준명")) {
        // txb_ISU_ABBRV.value = "";
        txb_ISU_ABBRV.focus();
        return false;
    }
    if (txb_ISU_ABBRV.getValue() === "" || txb_ISU_ABBRV.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글기준약명"));
        txb_ISU_ABBRV.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ABBRV, 20, "한글기준약명")) {
