        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목명"));
        txb_ISU_ENG_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ENG_NM, 60, "영문종목명")) {
        // txb_ISU_ENG_NM.value = "";
        txb_ISU_ENG_NM.focus();
        return false;
    }
    if (txb_ISU_ENG_ABBRV.getValue() === "" || txb_ISU_ENG_ABBRV.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목약명"));
        txb_ISU_ENG_ABBRV.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ENG_ABBRV, 20, "영문종목약명")) {
        // txb_ISU_ENG_ABBRV.value = "";
        txb_ISU_ENG_ABBRV.focus();
        return false;
    }
    if (txb_UNQ_ISU_NM.getValue() === "" || txb_UNQ_ISU_NM.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글고유명"));
        txb_UNQ_ISU_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_UNQ_ISU_NM, 20, "한글고유명")) {
        // txb_UNQ_ISU_NM.value = "";
        txb_UNQ_ISU_NM.focus();
        return false;
    }
    if (txb_UNQ_ISU_ENG_NM.getValue() === "" || txb_UNQ_ISU_ENG_NM.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문고유명"));
        txb_UNQ_ISU_ENG_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_UNQ_ISU_ENG_NM, 20, "영문고유명")) {
        // txb_UNQ_ISU_ENG_NM.value = "";
        txb_UNQ_ISU_ENG_NM.focus();
        return false;
    }
    if (Typ === "I") {

    } else if (Typ === "U") {

    }
    if (cmb_BND_TP_CD.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "채권유형"));
        cmb_BND_TP_CD.focus();
        return false;
    }
    if (txb_BND_CLSS_CD.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "채권분류코드"));
        txb_BND_CLSS_CD.focus();
        return false;
    }
    if (cmb_INFLLNK_YN.getValue() === "") {
        tab_UsrInfo.setSelectedTabIndex(1);
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "물가연동구분"));
        cmb_INFLLNK_YN.focus();
        return false;
    }
    if (txb_ISUR_CD.getValue() === "GB035") {

    } else {
        if (cmb_BND_TP_CD.getValue() === "GB") {

        } else {
            if (cmb_INFLLNK_YN.getValue() === "Y") {
                await $c.win.alert("물가연동구분은 채권유형이 국채일경우만 입력합니다. 채권유형을 확인해 주십시오.");
                tab_UsrInfo.setSelectedTabIndex(1);
                cmb_INFLLNK_YN.focus();
                return false;
            }
            if (edt_ISU_DD_REF_IDX.getValue() === "") {

            } else {
                await $c.win.alert("물가참조지수는 채권유형이 국채일경우만 입력합니다. 채권유형을 확인해 주십시오.");
