    	cmb_NUSUAL_BND_TP_CD.focus();

    	txb_OBJ_ISU_CD.value = "";
    	txb_OBJ_ISU_NM.value = "";
    	return false;
    } 	*/

    if (cmb_INT_PAY_METHD_CD.getValue() === "" || cmb_INT_PAY_METHD_CD.getValue().substring(0, 1) === "1") {
        if (txb_INT_RT_DECSN_MISC_BAS_INT_NM.getValue() !== "") {
            await $c.win.alert("금리연동탭은 변동금리시에만 입력합니다. 이자관련탭의 이자지급방법을 확인바랍니다.");
            tab_UsrInfo.setSelectedTabIndex(4);
            txb_INT_RT_DECSN_MISC_BAS_INT_NM.focus();
            return false;
        }
    }
    if (cmb_SPLIT_REDMPT_TP_CD.getValue() !== "" && cmb_REDMPT_METHD_TP_CD.getValue().substring(0, 1) !== "2") {
        await $c.win.alert("상환방법탭은 분할상환시에만 입력합니다. 발행조건의 상환방법을 확인바랍니다.");
        tab_UsrInfo.setSelectedTabIndex(9);
        cmb_SPLIT_REDMPT_TP_CD.focus();
        return false;
    }
    if (ckb_BND_ISU_METHD_CD1.getValue() === "N" && ckb_BND_ISU_METHD_CD2.getValue() === "N" &&
        ckb_BND_ISU_METHD_CD3.getValue() === "N") {
        tab_UsrInfo.setSelectedTabIndex(1);
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행방법"));
        return false;
    }
    if (cmb_ASST_SECUTIZ_TP_CD.getValue() === "" && txb_SECUTIZ_ADM_INST_CD.getValue() !== "") {
        await $c.win.alert("유동화탭은 유동화 채권일 경우에만 입력합니다. 유동화채권 인지 확인바랍니다.");
        tab_UsrInfo.setSelectedTabIndex(9);
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_INT_RT_DECSN_MISC_BAS_INT_NM, 20, "기타기준금리")) {
        tab_UsrInfo.setSelectedTabIndex(4);
        // txb_INT_RT_DECSN_MISC_BAS_INT_NM.value = "";
        txb_INT_RT_DECSN_MISC_BAS_INT_NM.focus();
        return false;
    }
    if (txb_CFI_CD.getValue() === "") {
        tab_UsrInfo.setSelectedTabIndex(10);
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "채권의 CFI"));
        txb_CFI_CD.focus();
        return false;
    }
    if (cmb_BND_TP_CD.getValue() === "AB") {
        if (txb_BND_CLSS_CD.getValue() === "") {
            await $c.win.alert("채권분류코드가 없습니다.");
            txb_CFI_CD.focus();
            return false;
        }
    }
    if (cmb_NUSUAL_BND_TP_CD.getValue() === "3" || cmb_NUSUAL_BND_TP_CD.getValue() === "4") {
        await $c.win.alert("ELS/DLS 는 수정할수 없습니다. ELS/DLS화면을 이용하세요.");
        cmb_NUSUAL_BND_TP_CD.focus();
        return false;
    }
    if (cmb_NUSUAL_BND_TP_CD.getValue() === "5") {
        await $c.win.alert("전자단기사채 는 수정할수 없습니다. 전자단기사채화면을 이용하세요.");
        cmb_NUSUAL_BND_TP_CD.focus();
        return false;
    }

    // 날짜포맷 체크
    if (fn_CheckDateObj(edt_ISU_DD, "발행일")) return false;
    if (fn_CheckDateObj(edt_REDMPT_DD, "상환일")) return false;
    if (fn_CheckDateObj(edt_SALE_DD, "선/후매출일")) return false;
    if (fn_CheckDateObj(edt_FST_INT_PAY_DD, "최초이자지급일")) return false;
    if (fn_CheckDateObj(edt_GRT_YD_STRT_DD, "보장수익률적용일")) return false;
    if (fn_CheckDateObj(edt_ADD_YD_STRT_DD, "추가수익률적용일")) return false;
    if (fn_CheckDateObj(edt_INT_RT_DECSN_BAS_DD, "최초표면이자율결정기준일")) return false;
    if (fn_CheckDateObj(edt_EXER_STRT_DD, "행사개시일")) return false;
    if (fn_CheckDateObj(edt_EXER_END_DD, "행사종료일")) return false;

    // 이자지급주기 1규칙 2불규칙
    /*
    if (getObjectValue(cmb_INT_PAY_UNIT_MMS) == "1"){
    	if (getObjectValue(txb_INT_PAY_UNIT_MMS) == ""){
    		tab_UsrInfo.ActiveIndex =2;
    		alert( getMessageParam("MSG-A005", "이자지급주기") );
    		txb_INT_PAY_UNIT_MMS.focus();
    		return false;
    	}
    }
     */

    // 이자계산주기 1규칙 2불규칙
    if (cmb_INT_PAY_CALC_MMS.getValue() === "1") {
        if (txb_INT_PAY_CALC_MMS.getValue() === "") {
            tab_UsrInfo.setSelectedTabIndex(2);
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "이자계산주기"));
            txb_INT_PAY_CALC_MMS.focus();
            return false;
        }
    }

    // 상환방법: 영구채 선택시 휴무관련(원금) : 해당없음 선택이 원칙이나 선택사항이므로 경고문구만 띄운다.
    if (cmb_REDMPT_METHD_TP_CD.getValue() === "3" && cmb_BK_HOLDY_PRINC_PAY_DD_DECSN_CD.getValue() !== "") {
        if (!window.confirm("상환방법이 '영구채'이며 휴무관련(원금)이 선택되었습니다.\n그래도 처리하시겠습니까?")) {
            return false;
        } else {
            return 1;
        }
    }
    if (!$c.stf.checkMaxLength(txa_NUSUAL_ISU_COND_CONTN, 60, "특이발행조건")) {
        // txb_ISU_ENG_ABBRV.value = "";
        txa_NUSUAL_ISU_COND_CONTN.focus();
        return false;
    }

    // 마이너스입력체크
    if (fn_minusCheck(edt_COUPN_RT, "표면이자율") === "N") {
        return false;
    }
    if (fn_minusCheck(edt_SCBD_INT, "낙찰금리") === "N") {
        return false;
    }
    if (fn_minusCheck(edt_BK_HOLDY_DD_PRINC_ACRINT_RT, "원금 경과금리") === "N") {
        return false;
    }
    if (fn_minusCheck(edt_BK_HOLDY_DD_INT_CMP_ACRINT_RT, "이자 경과금리") === "N") {
        return false;
    }
    if (fn_minusCheck(edt_GRT_YD, "보장수익률") === "N") {
        return false;
    }
    if (fn_minusCheck(edt_ADD_YD, "추가수익률") === "N") {
        return false;
    }

    // CFI체크
    if (cmb_cb_p_group.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_그룹"));
        cmb_cb_p_group.focus();
        return false;
    }
    if (cmb_cb_p_attr_1.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_1차속성"));
        cmb_cb_p_attr_1.focus();
        return false;
    }
    if (cmb_cb_p_attr_2.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_2차속성"));
        cmb_cb_p_attr_2.focus();
        return false;
    }
    if (cmb_cb_p_attr_3.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_3차속성"));
        cmb_cb_p_attr_3.focus();
        return false;
    }
    if (cmb_cb_p_attr_4.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_4차속성"));
        cmb_cb_p_attr_4.focus();
        return false;
    }
};

/**
 * @method
 * @name ins_chkRegisterStdCdCpBndInfo
 * @description 채권 표준코등록 전   채권분류코드 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_chkRegisterStdCdCpBndInfo = async function() {
    dts_detail.setCellData(dts_detail.getRowPosition(), "CRDUSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
    dts_CreditValuList.setCellData(dts_CreditValuList.getRowPosition(), "CRDUSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
    dts_AsstList.setCellData(dts_AsstList.getRowPosition(), "CRDUSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
    trs_chksave.KeyName = "toinb_dataid4";
    // [전환검토] trs_chksave.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     EMP_NO : js_emp_no,
    //     EMP_NM : js_emp_nm,
    //     EMAIL : js_email
    // };
    const sbmOptions = {
        id : "sbm_trs_chksave",
        action : "/StdCdBndInfoAction.do",
        ref : "dts_Rst,dts_detail",
        target : "trs_chksave=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name ins_modify
 * @description 채권 수정 한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_modify = async function() {
    if (await scwin.formCheck() === false) return;
    dts_detail.setCellData(dts_detail.getRowPosition(), "CRDUSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
    dts_CreditValuList.setCellData(dts_CreditValuList.getRowPosition(), "CRDUSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
    dts_AsstList.setCellData(dts_AsstList.getRowPosition(), "CRDUSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
    dts_callList.setBroadcast(false);
    for (let i = 1; i <= dts_callList.getRowCount(); i++) {
        dts_callList.setCellData(i, "CRDUSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
    }
    dts_callList.setBroadcast(true, true);
    dts_putList.setBroadcast(false);
    for (let i = 1; i <= dts_putList.getRowCount(); i++) {
        dts_putList.setCellData(i, "CRDUSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
    }
    dts_putList.setBroadcast(true, true);
    dts_BND_PAY_INT.setBroadcast(false);
    for (let i = 1; i <= dts_BND_PAY_INT.getRowCount(); i++) {
        dts_BND_PAY_INT.setCellData(i, "CRDUSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
    }
    dts_BND_PAY_INT.setBroadcast(true, true);
    trs_save.KeyName = "toinb_dataid4";
    // [전환검토] trs_save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     EMP_NO : js_emp_no,
    //     EMP_NM : js_emp_nm,
    //     EMAIL : js_email
    // };
    const sbmOptions = {
        id : "sbm_trs_save",
        action : "/StdCdBndInfoAction.do",
        ref : "dts_Rst2,dts_detail,dts_callList,dts_putList,dts_CreditValuList,dts_AsstList,dts_BND_PAY_INT",
        target : "trs_save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

