/**
 * @method
 * @name bNDISUMETHDCD
 * @description 발행방법 정의한다. 100 : 공모-간접발행, 010 : 공모-직접발행, 001 : 사모
 * @returns {void}
 * @hidden N
 */
scwin.bNDISUMETHDCD = function() {
    let BND_ISU_METHD_CD1 = ckb_BND_ISU_METHD_CD1.getValue();
    let BND_ISU_METHD_CD2 = ckb_BND_ISU_METHD_CD2.getValue();
    let BND_ISU_METHD_CD3 = ckb_BND_ISU_METHD_CD3.getValue();
    if (BND_ISU_METHD_CD1 === "Y") {
        BND_ISU_METHD_CD1 = "1";
    } else {
        BND_ISU_METHD_CD1 = "0";
    }
    if (BND_ISU_METHD_CD2 === "Y") {
        BND_ISU_METHD_CD2 = "1";
    } else {
        BND_ISU_METHD_CD2 = "0";
    }
    if (BND_ISU_METHD_CD3 === "Y") {
        BND_ISU_METHD_CD3 = "1";
    } else {
        BND_ISU_METHD_CD3 = "0";
    }
    txb_BND_ISU_METHD_CD.setValue(BND_ISU_METHD_CD1 + BND_ISU_METHD_CD2 + BND_ISU_METHD_CD3);
};

/**
 * @method
 * @name setBNDISUMETHDCD
 * @description 발행방법 정의한다. 100 : 공모-간접발행, 010 : 공모-직접발행, 001 : 사모
 * @returns {void}
 * @hidden N
 */
scwin.setBNDISUMETHDCD = function() {
    const BND_ISU_METHD_CD = txb_BND_ISU_METHD_CD.getValue();
    ckb_BND_ISU_METHD_CD1.setValue("N");
    ckb_BND_ISU_METHD_CD2.setValue("N");
    ckb_BND_ISU_METHD_CD3.setValue("N");
    if (BND_ISU_METHD_CD === "") return;
    let BND_ISU_METHD_CD1 = BND_ISU_METHD_CD.substring(0, 1);
    let BND_ISU_METHD_CD2 = BND_ISU_METHD_CD.substring(1, 2);
    let BND_ISU_METHD_CD3 = BND_ISU_METHD_CD.substring(2, 3);
    if (BND_ISU_METHD_CD1 === "1") {
        ckb_BND_ISU_METHD_CD1.setValue("Y");
    } else {
        ckb_BND_ISU_METHD_CD1.setValue("N");
    }
    if (BND_ISU_METHD_CD2 === "1") {
        ckb_BND_ISU_METHD_CD2.setValue("Y");
    } else {
        ckb_BND_ISU_METHD_CD2.setValue("N");
    }
    if (BND_ISU_METHD_CD3 === "1") {
        ckb_BND_ISU_METHD_CD3.setValue("Y");
    } else {
        ckb_BND_ISU_METHD_CD3.setValue("N");
    }
};

