/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = async function(rowcount) {
    if (dts_List.errorMsg) {
        await $c.win.alert(dts_List.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }

    // 조회버튼 활성.
    fn_SetDisableSelectBtn(btn_search, false);
    tab_UsrInfo.setSelectedTabIndex(1);
};

/**
 * @method
 * @name dts_detail_OnLoadCompleted
 * @description dts_detail 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_detail_OnLoadCompleted = async function(rowcount) {
    if (rowcount > 0) {
        fn_CtrlBtn_temp("update");
        const CFI_CD = dts_detail.getCellData(dts_detail.rowpositon, "CFI_CD");
        const SIMSA_YN = dts_detail.getCellData(dts_detail.rowpositon, "SIMSA_YN");
        const LIST_STAT_CD = dts_detail.getCellData(dts_detail.rowpositon, "LIST_STAT_CD");
        // set_Change("ECVTCN") ;
        scwin.setChange(CFI_CD);
        await scwin.setBndView(SIMSA_YN, LIST_STAT_CD);
        scwin.cOUPNRTDECSNBASINTCDChage();
        if (dts_detail.getCellData(dts_detail.rowpositon, "CASH_PAY_YN") === "Y") {
            ckb_CASH_PAY_YN.setValue("Y");
        } else {
            ckb_CASH_PAY_YN.setValue("N");
        }
        if (dts_detail.getCellData(dts_detail.rowpositon, "SB_PAY_YN") === "Y") {
            ckb_SB_PAY_YN.setValue("Y");
        } else {
            ckb_SB_PAY_YN.setValue("N");
        }
        scwin.setBNDISUMETHDCD();

        // 발행전국채거래 활성/비활성
        if (txb_ISUR_CD.getValue() === "GB035") {
            cmb_PRESALE_GOVBND_TRD_TP_CD.setDisabled(false);
            cmb_PRESALE_GOVBND_TRD_TP_CD.disableBackColor = '#ffffff';
        } else {
            cmb_PRESALE_GOVBND_TRD_TP_CD.setDisabled(true);
            cmb_PRESALE_GOVBND_TRD_TP_CD.disableBackColor = '#b9d4f7';
        }
    } else {
        fn_CtrlBtn_temp("no_data");
    }
    tab_UsrInfo.setSelectedTabIndex(1);
};

