/**
 * @method
 * @name btn_delete_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_delete_onclick = async function() {
    if (fn_checkSendTime(dts_time, "ULDINS15100.xml") === false) {
        await $c.win.alert("정보문의 전송 마감시간(19:00)이 초과되어 삭제하실수 없습니다.");
        return;
    }
    txb_param1.setValue("");
    txb_param2.setValue("");
    fn_GetPar = scwin.getParam;
    // 삭제 신청건수 확인후
    const DELCNT = dts_detail.getCellData(dts_detail.rowpositon, "DELCNT");
    if (Number(DELCNT) > 0) {
        // 삭제 메시지 확인 ... 확인되면 -> 삭제승인 화면이동 ,null,null, 아니면 바로 삭제
        fn_alertRequiredDelByWeb();
    } else {
        // 관리 삭제로직
        // 삭제팝업호출
        // 삭제사유 전달받을 input박스 정의한다.
        let rtn = fn_alertDelConfirm();
        if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

        {
            ins_popupOpen(txb_DEL_RSN, "", "ULDINS91500", "삭제사유", "470", "170");
        }
        // ins_remove() 함수를 자동호출 하므로 삭제 함수를 만들어 두어야 한다.

    }
};

