 * @description 「행삽입」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_AddSplit_onclick = async function() {
    if (cmb_SPLIT_REDMPT_TP_CD.getValue() === "3") {
        // 불균등일경우에만 추가 가능
        dts_BND_PAY_INT.insertRow();
    } else {
        await $c.win.alert("불균등일경우에만 행삽입 가능합니다.");
    }
};

