/**
 * @method
 * @name cmb_cb_p_group_onselchange
 * @description cmb_cb_p_group onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_cb_p_group_onselchange = function() {
    if (cmb_cb_p_group.getValue() !== "") {
        ins_cfi_set(dts_cfi_attr1, "ULDINS15100.xml", SCREN_PROCS_TP_CD_01, "01", "D", cmb_cb_p_group.getValue(), "1", "");
        ins_cfi_set(dts_cfi_attr2, "ULDINS15100.xml", SCREN_PROCS_TP_CD_01, "01", "D", cmb_cb_p_group.getValue(), "2", "");
        ins_cfi_set(dts_cfi_attr3, "ULDINS15100.xml", SCREN_PROCS_TP_CD_01, "01", "D", cmb_cb_p_group.getValue(), "3", "");
        ins_cfi_set(dts_cfi_attr4, "ULDINS15100.xml", SCREN_PROCS_TP_CD_01, "01", "D", cmb_cb_p_group.getValue(), "4", "");
        // alert(dts_cfi_attr1.NameValue(2,"HEAD_NM"));
        label_attr1.setValue("(" + dts_cfi_attr1.getCellData(2, "HEAD_NM") + ")");
        label_attr2.setValue("(" + dts_cfi_attr2.getCellData(2, "HEAD_NM") + ")");
        label_attr3.setValue("(" + dts_cfi_attr3.getCellData(2, "HEAD_NM") + ")");
        label_attr4.setValue("(" + dts_cfi_attr4.getCellData(2, "HEAD_NM") + ")");
    }
    scwin.changeCfi();
};

